function updateEnemies(dt){for(const e of enemies){if(e.hp<=0||e.type==='crate')continue;e.hit=Math.max(0,e.hit-dt);e.stun=Math.max(0,e.stun-dt);e.attack=Math.max(0,e.attack-dt);let target=[...actors.values()].sort((a,b)=>Math.hypot(a.x-e.x,a.z-e.z)-Math.hypot(b.x-e.x,b.z-e.z))[0];if(!target)continue;let dx=target.x-e.x,dz=target.z-e.z,d=Math.hypot(dx,dz);let charmed=e.type==='snake'&&game.flute>0;const pursue=d<9&&d>1.1&&!e.stun&&!charmed;let vx=0,vz=0;if(pursue){vx=dx/d;vz=dz/d;e.x+=vx*balance.enemySpeed*dt;e.z+=vz*balance.enemySpeed*dt}if(charmed){e.x+=Math.sin(t*2+e.id)*dt*.2;e.z+=Math.cos(t*2+e.id)*dt*.2}e.rig.group.position.set(e.x,e.hit>0?Math.sin(e.hit*25)*.2:0,e.z);if(pursue)e.rig.group.rotation.y=Math.atan2(dx,dz);e.rig.update(dt,pursue);if(d<1.35&&!charmed&&e.attack<=0&&e.stun<=0){damage(target,e.type==='snake'?1:1);e.attack=1.5}if(!isAttract&&e.type==='thief'&&d<1.5&&game.coins>0&&e.attack<=0){game.coins--;e.stolenCoins=(e.stolenCoins||0)+1;e.attack=3;toast('Light fingers! Whip the thief before he makes off.');}}}
