 if(simulation&&game.won&&isAttract){attractT+=dt;if(attractT>5){beginAttract();}}
 if(simulation&&!game.won){game.time+=dt;game.flute=Math.max(0,game.flute-dt);if(authority){const local=isAttract?autoInput(dt):paused?{}:input;if(!net.server){const a=localActor();if(a)applyActor(a,local,dt)}for(const [id,i] of remoteInputs){const a=actors.get(id);if(a&&a!==localActor()||a&&net.server)applyActor(a,t-i.received<.5?i:{},dt);i.attack=i.interact=i.roll=i.tool=false;}physics.timestep=dt;physics.step();updateEnemies(dt);updateTraps(dt);}else{const send=paused?{}:input;pendingGuest={...pendingGuest,...send,attack:pendingGuest.attack||send.attack||queuedGuest.attack,interact:pendingGuest.interact||send.interact||queuedGuest.interact,roll:pendingGuest.roll||send.roll,tool:pendingGuest.tool||send.tool};queuedGuest={};if(netTimer<=0){net.sendInput(pendingGuest);pendingGuest={}}for(const a of actors.values()){a.update(dt,{moving:a.moving,attack:a.attack>0,rolling:a.roll>0,flute:game.flute>0});a.whip.group.visible=a.attack>0;a.whip.update(1-a.attack/.32)}}}
 world?.props.setHazards?.({enabled:stage===1&&!game.flags.map||stage===3&&!!game.escape,time:t*balance.trapSpeed,escapeTime:game.escapeTime});world?.update(t,dt);for(let i=particles.length-1;i>=0;i--){const p=particles[i];p.life-=dt;p.v.y-=9*dt;p.mesh.position.addScaledVector(p.v,dt);p.mesh.rotation.x+=dt*3;if(p.life<=0){scene.remove(p.mesh);p.mesh.geometry.dispose();p.mesh.material.dispose();particles.splice(i,1)}}
 if(stage===3&&world?.props.ark)world.props.ark.rotation.y=Math.sin(t*.5)*.08;
 if(beamTimer<=0){updateBeams();beamTimer=.2}beamTimer-=dt;
