 window.__game={get state(){return{...snapshot(),mode,screen,isAttract,renderer:renderer.backend.isWebGPUBackend?'webgpu':'webgl',physics:'rapier-0.19.3',ready:gameReady,audio:audio.getStats(),network:{active:net.active,host:net.isHost,connected:net.connected,code:net.code,transport:net.transport},balance:{...balance},context:contextTarget?.id}},start:()=>startGame(false),action,interact:()=>interact(localActor()),input:(i,seconds=1)=>{for(let j=0;j<Math.ceil(seconds*60);j++)update(1/60,i)},moveTo:(x,z,seconds=6)=>{for(let j=0;j<seconds*60;j++){const a=localActor(),dx=x-a.x,dz=z-a.z,d=Math.hypot(dx,dz);if(d<.15)break;update(1/60,{mx:(dx*.83-dz*.55)/d,mz:(dx*.55+dz*.83)/d})}return{x:localActor().x,z:localActor().z}},aim:(x,z)=>{mouseAim=null;localActor().angle=Math.atan2(x-localActor().x,z-localActor().z)},advance:s=>{for(let i=0;i<s*60;i++)update(1/60,{})},attract:beginAttract,exitAttract:stopAttract,network:net,audio,testAudioOffline,warp:(i)=>{game.flags={kit:true,seal:true,map:true,assisted:true,god:true};loadStage(i,false)},idle:seconds=>{idleSince=performance.now()-seconds*1000;update(1/60,{})},position:(x,z,id)=>positionActor(id===undefined?localActor():actors.get(id),x,z),restoreCheckpoint:()=>{const s=readStore('hieroglyph-checkpoint',null);if(s){startGame(false);Object.assign(game,{score:s.score,coins:s.coins,flags:s.flags,time:s.time});loadStage(s.stage);return true}return false},get diagnostics(){return{renderCalls:renderer.info.render.calls,triangles:renderer.info.render.triangles,colliders:physics.colliders.len(),rigs:[...actors.values()].map(a=>({id:a.id,mixer:a.mixer instanceof THREE.AnimationMixer,clips:a.mixer?._actions?.length})),enemies:enemies.map(e=>({type:e.type,x:e.x,z:e.z,hp:e.hp})),markers:markers.map(m=>({id:m.id,x:m.x,z:m.z})),rapierBodies:physics.bodies.len()}}};
